import{_ as t,c as a,o as i,a6 as o}from"./chunks/framework.B5rgnJXo.js";const u=JSON.parse('{"title":"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机","description":"Wiz Threat Research 90 天蜜罐遥测全景：CVE-2026-59822 单字符 Bearer 认证绕过、CVE-2026-42271 MCP 测试端点命令注入、Qilin 勒索组织关联攻击链、内存提取 master key、盲提示注入与 XMRig 挖矿载荷伪装，附完整 IoC 与防御清单","frontmatter":{"title":"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机","description":"Wiz Threat Research 90 天蜜罐遥测全景：CVE-2026-59822 单字符 Bearer 认证绕过、CVE-2026-42271 MCP 测试端点命令注入、Qilin 勒索组织关联攻击链、内存提取 master key、盲提示注入与 XMRig 挖矿载荷伪装，附完整 IoC 与防御清单","date":"2026-09-14T00:00:00.000Z","category":"security","tags":["litellm","mcp","ai安全","honeypot","qilin","xmrig","威胁情报"],"recommend":"安全工程","keywords":["Wiz 蜜罐","LiteLLM 攻击","MCP 安全","CVE-2026-59822","CVE-2026-42271","Qilin 勒索软件","AI 基础设施安全"],"head":[["link",{"rel":"canonical","href":"https://friday-go.icu/security/offensive/wiz-ai-infrastructure-honeypot-90days-2026"}],["meta",{"property":"og:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"twitter:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"keywords","content":"Wiz 蜜罐,LiteLLM 攻击,MCP 安全,CVE-2026-59822,CVE-2026-42271,Qilin 勒索软件,AI 基础设施安全, PFinalClub, Golang教程, Go后端开发, Go微服务, PHP, Python, 技术博客"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"article:published_time","content":"2026-09-14T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-14T01:29:12.000Z"}],["meta",{"property":"article:author","content":"PFinal南丞"}],["meta",{"property":"article:section","content":"攻防研究"}],["meta",{"property":"article:tag","content":"litellm"}],["meta",{"property":"article:tag","content":"mcp"}],["meta",{"property":"article:tag","content":"ai安全"}],["meta",{"property":"article:tag","content":"honeypot"}],["meta",{"property":"article:tag","content":"qilin"}],["meta",{"property":"article:tag","content":"xmrig"}],["meta",{"property":"article:tag","content":"威胁情报"}],["meta",{"name":"citation_title","content":"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机"}],["meta",{"name":"citation_author","content":"PFinal南丞"}],["meta",{"name":"citation_date","content":"2026-09-14"}],["meta",{"name":"citation_online_date","content":"2026-09-14"}],["meta",{"property":"og:title","content":"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机"}],["meta",{"property":"og:description","content":"Wiz Threat Research 90 天蜜罐遥测全景：CVE-2026-59822 单字符 Bearer 认证绕过、CVE-2026-42271 MCP 测试端点命令注入、Qilin 勒索组织关联攻击链、内存提取 master key、盲提示注入与 XMRig 挖矿载荷伪装，附完整 IoC 与防御清单"}],["meta",{"property":"og:url","content":"https://friday-go.icu/security/offensive/wiz-ai-infrastructure-honeypot-90days-2026"}],["meta",{"name":"twitter:title","content":"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机"}],["meta",{"name":"twitter:description","content":"Wiz Threat Research 90 天蜜罐遥测全景：CVE-2026-59822 单字符 Bearer 认证绕过、CVE-2026-42271 MCP 测试端点命令注入、Qilin 勒索组织关联攻击链、内存提取 master key、盲提示注入与 XMRig 挖矿载荷伪装，附完整 IoC 与防御清单"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机\\",\\"url\\":\\"https://friday-go.icu/security/offensive/wiz-ai-infrastructure-honeypot-90days-2026\\",\\"datePublished\\":\\"2026-09-14T00:00:00.000Z\\",\\"dateModified\\":\\"2026-09-14T01:29:12.000Z\\",\\"wordCount\\":15500,\\"timeRequired\\":\\"PT52M\\",\\"proficiencyLevel\\":\\"Advanced\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"PFinal南丞\\",\\"url\\":\\"https://friday-go.icu/about\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"PFinalClub\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://friday-go.icu/logo.png\\"}},\\"description\\":\\"Wiz Threat Research 90 天蜜罐遥测全景：CVE-2026-59822 单字符 Bearer 认证绕过、CVE-2026-42271 MCP 测试端点命令注入、Qilin 勒索组织关联攻击链、内存提取 master key、盲提示注入与 XMRig 挖矿载荷伪装，附完整 IoC 与防御清单\\",\\"inLanguage\\":\\"zh-CN\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://friday-go.icu/security/offensive/wiz-ai-infrastructure-honeypot-90days-2026\\"},\\"keywords\\":[\\"Wiz 蜜罐\\",\\"LiteLLM 攻击\\",\\"MCP 安全\\",\\"CVE-2026-59822\\",\\"CVE-2026-42271\\",\\"Qilin 勒索软件\\",\\"AI 基础设施安全\\"],\\"articleSection\\":\\"攻防研究\\"}"],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"安全\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"攻防研究\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":4,\\"name\\":\\"Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive/wiz-ai-infrastructure-honeypot-90days-2026\\",\\"@type\\":\\"Article\\"}}]}"]]},"headers":[],"relativePath":"security/offensive/wiz-ai-infrastructure-honeypot-90days-2026.md","filePath":"security/offensive/wiz-ai-infrastructure-honeypot-90days-2026.md","lastUpdated":1789349352000}'),r={name:"security/offensive/wiz-ai-infrastructure-honeypot-90days-2026.md"};function n(s,e,c,l,d,p){return i(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o(`<h1 id="wiz-90-天-ai-蜜罐报告-攻击者如何把-litellm-与-mcp-服务器变成提款机" tabindex="-1">Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机 <a class="header-anchor" href="#wiz-90-天-ai-蜜罐报告-攻击者如何把-litellm-与-mcp-服务器变成提款机" aria-label="Permalink to &quot;Wiz 90 天 AI 蜜罐报告：攻击者如何把 LiteLLM 与 MCP 服务器变成提款机&quot;">​</a></h1><blockquote><p>TL;DR：Wiz Threat Research 将 LiteLLM、Flowise、LangChain、Langflow、ChromaDB、Ollama、Node-RED 等 AI 服务暴露在公网上当蜜罐，跑了 90 天。结论：这不是泛型扫描——攻击者带着对每个服务内部实现的精确了解而来，包括&quot;哪个 Python 对象里存着 LiteLLM master key&quot;。三条主线：MCP 服务器 RCE（CVE-2026-59822 + CVE-2026-42271 链，关联 Qilin 勒索组织）、盲提示注入转 Shell、AI 原生后渗透（内存提取密钥、<code>.claude/unicorn</code> 伪装）。防御核心一句话：<strong>把 AI 网关当特权基础设施管，而不是当一个网页服务</strong>。</p></blockquote><h2 id="一、为什么-ai-基础设施成了主流攻击面" tabindex="-1">一、为什么 AI 基础设施成了主流攻击面 <a class="header-anchor" href="#一、为什么-ai-基础设施成了主流攻击面" aria-label="Permalink to &quot;一、为什么 AI 基础设施成了主流攻击面&quot;">​</a></h2><p>Wiz《State of AI in the Cloud》的数据：<strong>90% 的云环境运行自托管 AI 软件，81% 使用托管 AI 服务，63% 自托管 AI 模型</strong>。蜜罐里跑的每个服务，都有大量真实企业在线上裸奔着同款部署。</p><p>攻击者盯着 AI 基础设施，看中的是两个特性：</p><ol><li><strong>凭证集中</strong>。一个 LiteLLM 代理可能持有它路由到的所有模型供应商的 key——OpenAI、Anthropic、Azure、Gemini——外加云 IAM 权限和通过 MCP tool server 连接的内部系统。攻破一个代理，拿到的是它下游的一切，而不只是代理本身。</li><li><strong>Agent 可达性</strong>。AI Agent 的设计目标就是&quot;接受外部输入并执行工具&quot;。这个可达性天然给了攻击者注入指令的通道——输入直接驱动工具执行。</li></ol><p>对应此前<a href="/security/offensive/ai-ml-infrastructure-attack-mlflow-rclone-cve-2026">MLflow/Rclone 攻击链分析</a>的趋势判断：AI 基础设施已经从&quot;顺带扫到&quot;升级为&quot;专门定制&quot;的目标。</p><h2 id="二、模式一-mcp-服务器-rce" tabindex="-1">二、模式一：MCP 服务器 RCE <a class="header-anchor" href="#二、模式一-mcp-服务器-rce" aria-label="Permalink to &quot;二、模式一：MCP 服务器 RCE&quot;">​</a></h2><p>MCP 让 AI Agent 调用外部工具服务器——数据库、代码仓库、Slack、内部 API。暴露在公网的 MCP 服务器等于把内部系统的调用面直接挂在了互联网上。蜜罐观测到两个被真实利用的 LiteLLM MCP 漏洞。</p><h3 id="_2-1-cve-2026-59822-一个字符的-bearer-token" tabindex="-1">2.1 CVE-2026-59822：一个字符的 Bearer Token <a class="header-anchor" href="#_2-1-cve-2026-59822-一个字符的-bearer-token" aria-label="Permalink to &quot;2.1 CVE-2026-59822：一个字符的 Bearer Token&quot;">​</a></h3><p>漏洞位于 LiteLLM MCP Gateway 的 OAuth2 header 处理：<strong>token 校验失败时，服务器不是拒绝请求，而是返回一个没有任何限制的空 <code>UserAPIKeyAuth()</code> 对象</strong>。结果就是任意 Bearer token 都能通过——哪怕只有一个字符：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /v1/models HTTP/1.1</span></span>
<span class="line"><span>Authorization: Bearer x</span></span></code></pre></div><p>蜜罐里真实捕获到攻击者用单字符 token 探测模型枚举端点。该漏洞影响 1.84.0 之前版本，修复于 1.84.0+。</p><h3 id="_2-2-cve-2026-42271-会执行任意命令的-测试连接-按钮" tabindex="-1">2.2 CVE-2026-42271：会执行任意命令的&quot;测试连接&quot;按钮 <a class="header-anchor" href="#_2-2-cve-2026-42271-会执行任意命令的-测试连接-按钮" aria-label="Permalink to &quot;2.2 CVE-2026-42271：会执行任意命令的&quot;测试连接&quot;按钮&quot;">​</a></h3><p>我们在<a href="/security/offensive/litellm-cve-2026-42271-mcp-injection-exploitation">上一篇文章</a>里已完整复现过这个漏洞（CVSS 8.7，2026 年 6 月进入 CISA KEV）的利用细节，这里只讲 Wiz 蜜罐观测到的<strong>真实载荷</strong>：</p><p>LiteLLM 的 MCP server test endpoint 允许用户在保存前测试 MCP server 配置，但 <code>command</code> 字段<strong>未经验证直接进入 subprocess 执行</strong>。攻击者提交了一个假的 MCP stdio server 配置，<code>command</code> 字段是一段 Python 脚本：</p><ol><li>从 <code>http://185.62.1.8/mon/mon.zip</code> 下载压缩包；</li><li>解压出 Monero 挖矿程序 <code>gmon</code> 到 <code>/tmp/.dbus-cache/</code>；</li><li>以 <code>start_new_session=True</code> 脱离会话启动挖矿进程；</li><li><strong>删除暂存目录</strong>——但运行中的进程保持着二进制文件的 inode，所以挖矿继续跑，磁盘上却几乎不留痕迹；</li><li>返回一个合法的 MCP handshake，让&quot;连接测试&quot;看起来完全成功。</li></ol><p>一个带验证功能的测试端点，本身就是危险设计：<strong>任何&quot;会运行你配置的命令来验证连接&quot;的端点都是 RCE 面</strong>。</p><h3 id="_2-3-链上-starlette-绕过-完全未认证的-rce" tabindex="-1">2.3 链上 Starlette 绕过：完全未认证的 RCE <a class="header-anchor" href="#_2-3-链上-starlette-绕过-完全未认证的-rce" aria-label="Permalink to &quot;2.3 链上 Starlette 绕过：完全未认证的 RCE&quot;">​</a></h3><p>CVE-2026-42271 与 Starlette 的 Host header 校验绕过（<a href="/security/offensive/cve-2026-48710-starlette-badhost-auth-bypass">CVE-2026-48710</a>）链接后，可以实现<strong>完全未认证的远程代码执行</strong>。外部研究人员将这条利用链与 <strong>Qilin 勒索组织</strong>关联起来——勒索软件开始从 AI 网关下手，这个信号值得所有运维团队警惕。</p><h2 id="三、模式二-盲提示注入转-shell" tabindex="-1">三、模式二：盲提示注入转 Shell <a class="header-anchor" href="#三、模式二-盲提示注入转-shell" aria-label="Permalink to &quot;三、模式二：盲提示注入转 Shell&quot;">​</a></h2><p>针对 LangChain、Flowise、OpenWebUI、Node-RED 等框架，蜜罐记录到大量<strong>盲提示注入</strong>：</p><ul><li>攻击者在普通请求内容里嵌入指令覆盖（instruction-override）载荷，诱导 Agent 调用 shell 工具执行操作系统命令；</li><li>因为注入结果不直接可见，攻击者用<strong>出带 DNS 回调</strong>确认执行——命令的唯一可见效果就是对攻击者控制域名的一次 DNS 查询；</li><li>载荷托管在 Pastebin，base64 编码以躲避日志和简单过滤器；</li><li>成功会话最终部署 XMRig，路径选在 <code>/usr/src/node-red/xmrig</code>——故意藏在 Node.js 进程树里。</li></ul><p>这个模式的技术本质和<a href="/security/offensive/cve-2026-49471-serena-mcp-dns-rebinding-rce">SerenA MCP DNS rebinding RCE</a>如出一辙：<strong>给 Agent shell 权限是一个高危设计决策</strong>，提示注入只是让这个决策变现的催化剂。</p><h2 id="四、模式三-ai-原生后渗透——从内存里捞-key" tabindex="-1">四、模式三：AI 原生后渗透——从内存里捞 key <a class="header-anchor" href="#四、模式三-ai-原生后渗透——从内存里捞-key" aria-label="Permalink to &quot;四、模式三：AI 原生后渗透——从内存里捞 key&quot;">​</a></h2><p>这是整份报告里最值得坐下来琢磨的部分。攻击者的后渗透动作完全围绕 AI 系统内部结构定制：</p><h3 id="_4-1-master-key-不落盘-那就从进程内存里拿" tabindex="-1">4.1 master key 不落盘，那就从进程内存里拿 <a class="header-anchor" href="#_4-1-master-key-不落盘-那就从进程内存里拿" aria-label="Permalink to &quot;4.1 master key 不落盘，那就从进程内存里拿&quot;">​</a></h3><p>LiteLLM 的 master key 从不写到文件系统。传统翻配置文件的思路失效，攻击者直接查询运行中的 Python 进程状态：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> litellm</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 检查 litellm.proxy.proxy_server 的属性</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># master_key、litellm_master_key_hash 就在内存里</span></span></code></pre></div><p>这不是通用后渗透脚本改一改就能干的事——需要攻击者专门读过 LiteLLM 源码。蜜罐还观测到对 <code>/app/litellm_config.yaml</code>、<code>/etc/litellm/.env</code>、<code>~/.litellm/config.yaml</code> 等标准配置路径的枚举。</p><h3 id="_4-2-先指纹-再决定-偷-key-还是-蹭算力" tabindex="-1">4.2 先指纹，再决定&quot;偷 key&quot;还是&quot;蹭算力&quot; <a class="header-anchor" href="#_4-2-先指纹-再决定-偷-key-还是-蹭算力" aria-label="Permalink to &quot;4.2 先指纹，再决定&quot;偷 key&quot;还是&quot;蹭算力&quot;&quot;">​</a></h3><p>动手前，攻击者会先用默认凭证（比如大名鼎鼎的 <code>sk-1234</code>）通过 chat-completion 请求让模型自报家门，摸清后端有哪些模型，再决定是直接窃取 key，还是安静地烧别人额度（AI token jacking）。</p><h3 id="_4-3-claude-unicorn-伪装成-ai-开发环境的一部分" tabindex="-1">4.3 <code>.claude/unicorn</code>：伪装成 AI 开发环境的一部分 <a class="header-anchor" href="#_4-3-claude-unicorn-伪装成-ai-开发环境的一部分" aria-label="Permalink to &quot;4.3 \`.claude/unicorn\`：伪装成 AI 开发环境的一部分&quot;">​</a></h3><p>Langflow 蜜罐里，攻击者把挖矿二进制放在 <code>/app/data/.claude/</code> 目录并命名为 <code>unicorn</code>——因为在一台跑着 AI 工具链的机器上，<code>.claude</code> 目录看起来就像 Claude Code 的合法配置目录，混在里面没人多看一眼。这和<a href="/security/offensive/ai-coding-agent-git-config-supply-chain-attack-2026">AI 编码代理 .git 配置供应链攻击</a>是同一思路：<strong>AI 工具链的&quot;正常存在&quot;正在被武器化</strong>。</p><h2 id="五、ioc-速查表" tabindex="-1">五、IoC 速查表 <a class="header-anchor" href="#五、ioc-速查表" aria-label="Permalink to &quot;五、IoC 速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>IP</td><td><code>185.62.1[.]8</code></td><td>LiteLLM/MCP 恶意载荷下载服务器</td></tr><tr><td>IP</td><td><code>94.26.106[.]29</code></td><td>二进制暂存</td></tr><tr><td>IP</td><td><code>185.84.98[.]85</code></td><td>挖矿程序 C2</td></tr><tr><td>域名</td><td><code>crazyeltonproxy[.]top</code></td><td>Monero 挖矿代理</td></tr><tr><td>域名</td><td><code>pool.hashvault[.]pro</code></td><td>Monero 矿池</td></tr><tr><td>文件</td><td><code>/tmp/.dbus-cache/gmon</code></td><td>Monero 挖矿二进制</td></tr><tr><td>文件</td><td><code>/tmp/x86_64</code>、<code>/tmp/amd64</code></td><td>dropper</td></tr><tr><td>文件</td><td><code>/usr/src/node-red/xmrig</code></td><td>伪装进 Node.js 进程树的挖矿程序</td></tr><tr><td>文件</td><td><code>/app/data/.claude/unicorn</code></td><td>伪装成 Claude Code 配置的挖矿二进制</td></tr></tbody></table><p>进程行为特征：AI 服务器进程异常 spawn shell、创建后立即删除的暂存目录、计划任务里出现 <code>authorized_keys</code> 变更、异常 DNS 出带。</p><h2 id="六、防御清单" tabindex="-1">六、防御清单 <a class="header-anchor" href="#六、防御清单" aria-label="Permalink to &quot;六、防御清单&quot;">​</a></h2><p>Wiz 的建议很直白：<strong>大多数此类工具默认无认证，把&quot;无认证暴露在互联网上&quot;直接当&quot;已被入侵&quot;处理</strong>。</p><ol><li><strong>立即升级 LiteLLM ≥ 1.84.0</strong>，并确认依赖没有锁死在受影响版本（42271 修复在 1.83.7+）；</li><li><strong>收敛 MCP 和管理端点</strong>：禁用不用的路由，测试端点仅限可信用户，绝不公网暴露；</li><li><strong>网关后置</strong>：反代、WAF、VPN 或内网负载均衡挡在前面，避免直连；</li><li><strong>最小权限 + 分段</strong>：供应商 key、云角色、服务账号、MCP 工具权限全部收窄，AI 系统与敏感基础设施隔离；</li><li><strong>管控出站流量</strong>：限制不必要的 DNS 和 HTTP 出带，对异常回调、载荷下载、模型枚举告警——盲提示注入依赖 DNS 出带确认，掐断它等于废掉整条利用链；</li><li><strong>按&quot;凭证已泄露&quot;标准响应</strong>：一旦网关失陷，轮换的不仅是 LiteLLM 凭证，还包括它可达的每一个 MCP 连接、云凭证和下游服务——内存里的 master key 无法&quot;删除&quot;，只能轮换使其失效；</li><li><strong>修正补丁节奏</strong>：开源 AI 基础设施的攻击者常常在 CVE 编号分配之前就武器化新合入的修复代码，&quot;等维护窗口再打补丁&quot;在这个领域是错误姿势。</li></ol><h2 id="七、写在最后" tabindex="-1">七、写在最后 <a class="header-anchor" href="#七、写在最后" aria-label="Permalink to &quot;七、写在最后&quot;">​</a></h2><p>这份报告最有价值的不是某个 CVE，而是一个结构性判断：<strong>AI 安全能做的最糟糕的事，就是让团队以为它和&quot;普通基础设施安全&quot;是两个科目</strong>。AI 网关坐在用户、云账号、付费模型服务和内部工具之间，一个配置弱点就足以放大成企业级事件。</p><p>MCP 安全系列此前已覆盖 <a href="/security/offensive/litellm-cve-2026-42271-mcp-injection-exploitation">LiteLLM CVE-2026-42271 利用实战</a>、<a href="/security/offensive/cve-2026-48710-starlette-badhost-auth-bypass">Starlette BadHost 绕过</a>、<a href="/security/offensive/cve-2026-49471-serena-mcp-dns-rebinding-rce">SerenA DNS rebinding</a>与 <a href="/security/offensive/ai-ml-infrastructure-attack-mlflow-rclone-cve-2026">MLflow/Rclone 攻击链</a>。本文补上攻击者 TTP 全景这一块——后续如果 Wiz 公开更多遥测细节，会继续跟进。</p><hr><p><em>参考：<a href="https://wiz.io/blog/ai-infrastructure-honeypot" target="_blank" rel="noreferrer">Wiz 博客原文 Inside 90 days of attacks on AI infrastructure</a>（2026-08-27 发布，作者 Yaara Shriki）、<a href="https://www.esecurityplanet.com/sites/esecurityplanet.com/news/news-litellm-mcp-server-attacks" target="_blank" rel="noreferrer">eSecurity Planet 报道</a>。</em></p>`,45)]))}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
